import {shops} from './shops.js';
import {shopAddonRows} from './shop-addon-data.js';
import {sourceAddon,sourceAddonFields,validateAddon} from './addon-data.js';
import {addonStatusHtml,mountAddonVariants} from './addon-ui.js';
import {mountProductSearch} from './product-search.js';
import {selectableComponents} from './component-policy.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountShopAddons(root,{original,getRows,getCosts,getOriginal,onChange=()=>{}}){
 const entries=shopAddonRows(getRows(),original,shops),base=sourceAddon(original),$=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)];
 const common=a=>JSON.stringify([a.goodsId||'',a.qty??1,a.note||'']);const mixed=new Set(entries.filter(e=>e.row).map(e=>common(sourceAddon(e.row)))).size>1;
 root.innerHTML=`<div class="shop-addon-actions"><button type="button" data-shop-addon-only>只修改当前店铺</button><button type="button" data-shop-addon-all>选择三店</button><span class="hint" data-shop-addon-scope></span></div><div class="shop-addon-common"><h5>共同信息</h5><div data-addon-product-search></div><div class="inline-grid"><label class="field">加购数量<input data-addon-qty type="number" min="1" step="1" value="${base.qty??1}"></label><label class="field">加购说明<input data-addon-note value="${esc(base.note)}"></label></div><label class="shop-addon-common-toggle"><input type="checkbox" data-addon-common> 将共同信息应用到勾选店铺</label><p class="hint">${mixed?'三店共同信息存在差异，当前显示本店设置。':'商品、数量和说明在这里统一维护。'}只修改价格和描述时，各店原有共同信息保留。</p></div><div class="shop-addon-grid">${entries.map(({shop,row,reason})=>{const a=row?sourceAddon(row):{};return `<section class="shop-addon-card" data-addon-shop="${shop.id}"><label class="shop-addon-heading"><input type="checkbox" data-shop-enabled ${row?'':'disabled'} ${row&&shop.id===original.shopId?'checked':''}><strong>${esc(shop.shortName)}</strong>${shop.id===original.shopId?'<small>当前店铺</small>':''}</label>${row?`<fieldset><label class="field">加购价（合计）<input data-addon-price type="number" min="0" step=".01" value="${a.priceCents==null?'':(a.priceCents/100).toFixed(2)}"></label><label class="field">加购描述<textarea data-addon-text rows="3">${esc(a.text)}</textarea></label><details><summary>维护其他可选加购描述</summary><div data-addon-variants></div></details></fieldset><small class="hint" data-shop-addon-original></small><div data-addon-check></div>`:`<p class="hint">${esc(reason)}</p>`}</section>`;}).join('')}</div><p class="hint">差价 = 原配件价格 ＋ 加购价 − 新配件成本价。ERP、核算分别比较，原、新配件单价均乘加购数量。</p>`;
 const card=id=>$(`[data-addon-shop="${id}"]`),enabled=id=>card(id).querySelector('[data-shop-enabled]').checked;
 let picker;const variantEditors=new Map();for(const entry of entries.filter(e=>e.row))variantEditors.set(entry.shop.id,mountAddonVariants(card(entry.shop.id).querySelector('[data-addon-variants]'),{initial:sourceAddon(entry.row).variants||[],sourceId:entry.row.sourceId,getCosts,getOriginals:()=>[entry.shop.id===original.shopId?getOriginal():entry.row],onChange:()=>{if(picker)refresh();}}));
 function readEntry(entry,required=false){const a=sourceAddon(entry.row),node=card(entry.shop.id);if(!enabled(entry.shop.id))return a;const raw=node.querySelector('[data-addon-price]').value;if(raw!==''&&!/^\d+(\.\d{1,2})?$/.test(raw))throw Error(entry.shop.shortName+'加购价最多两位小数');const value={...a,text:node.querySelector('[data-addon-text]').value.trim(),priceCents:raw===''?null:Math.round(Number(raw)*100)};if($('[data-addon-common]').checked)Object.assign(value,{goodsId:picker.value(),qty:Number($('[data-addon-qty]').value),note:$('[data-addon-note]').value.trim()});const variants=variantEditors.get(entry.shop.id)?.read(required)||[];if(variants.length||a.variants!==undefined)value.variants=variants;validateAddon(value,{required:required&&!!value.text.trim(),costs:getCosts()});return value;}
 function refresh(){for(const entry of entries){if(!entry.row)continue;const node=card(entry.shop.id),selected=enabled(entry.shop.id);node.classList.toggle('is-selected',selected);node.querySelector('fieldset').disabled=!selected;try{const a=readEntry(entry);node.querySelector('[data-shop-addon-original]').textContent=`商品 ID ${a.goodsId||'待关联'} · 数量 ${a.qty??1}${a.note?' · '+a.note:''}`;node.querySelector('[data-addon-check]').innerHTML=addonStatusHtml(a,getCosts(),[entry.shop.id===original.shopId?getOriginal():entry.row]);}catch(e){node.querySelector('[data-addon-check]').textContent=e.message;}}$('[data-shop-addon-scope]').textContent='本次修改：'+entries.filter(e=>e.row&&enabled(e.shop.id)).map(e=>e.shop.shortName).join('、');onChange();}
 const commonChanged=()=>{$('[data-addon-common]').checked=true;refresh();};
 picker=mountProductSearch($('[data-addon-product-search]'),{getRows:()=>selectableComponents(getCosts()),selected:base.goodsId,label:'加购商品',onChange:commonChanged});
 for(const el of all('.shop-addon-common [data-addon-qty],.shop-addon-common [data-addon-note]'))el.addEventListener('input',commonChanged);
 for(const el of all('[data-shop-enabled],[data-addon-common],[data-addon-price],[data-addon-text]'))el.addEventListener('input',refresh);
 $('[data-shop-addon-only]').onclick=()=>{for(const e of entries)card(e.shop.id).querySelector('[data-shop-enabled]').checked=!!e.row&&e.shop.id===original.shopId;refresh();};
 $('[data-shop-addon-all]').onclick=()=>{for(const e of entries)card(e.shop.id).querySelector('[data-shop-enabled]').checked=!!e.row;refresh();};
 function changes(required=true){return entries.filter(e=>e.row&&enabled(e.shop.id)).flatMap(e=>{const addon=readEntry(e,required),before=sourceAddonFields(sourceAddon(e.row));return JSON.stringify(before)===JSON.stringify(sourceAddonFields(addon))?[]:[{sourceId:e.row.sourceId,shopId:e.shop.id,before,addon}];});}
 refresh();return {read:(required=true)=>readEntry(entries.find(e=>e.shop.id===original.shopId),required),changes,refresh,isDirty:()=>{try{return changes(false).length>0;}catch{return true;}}};
}
